import{z as s,x as A,o as t,c as p,q as o,j as B,D as E,d as e,s as l,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"二元掩模与衰减相移","description":"","frontmatter":{"title":"二元掩模与衰减相移","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/binary-attpsm.md","filePath":"litho/binary-attpsm.md","lastUpdated":1791413859000}'),h={name:"litho/binary-attpsm.md"};function d(C,a,f,m,c,D){const r=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="二元掩模与衰减相移" tabindex="-1">二元掩模与衰减相移 <a class="header-anchor" href="#二元掩模与衰减相移" aria-label="Permalink to &quot;二元掩模与衰减相移&quot;">​</a></h1><div class="epigraph"><p>产线订的 DUV 版，多数是铬二元或 MoSi 衰减相移两类产品；相位机制上一课已经讲过，本课钉的是薄掩模透过率合同。</p><footer>—— 据 Levenson 之后的量产膜系惯例，以及 Mack、Levinson 对 binary 与 att-PSM 的表述整理</footer></div><p><a href="/litho/phase-shift-mask">上一课</a>（相移掩模 PSM）。说明了 \\(180^\\circ\\) 如何在暗区制造相消，并区分了交替型与衰减型。缺口是：晶圆厂下单时面对的是两类标准透射掩模——二元铬（COG）与嵌入式衰减相移（att-PSM，典型 MoSi）——以及还在用的 Kirchhoff 薄掩模假设。交替相移怎么用 trim 换节距、套刻进哪本账，留给<a href="/litho/alt-psm">下一课</a>；吸收体真正的厚度怎样捣乱，是后面<a href="/litho/mask-3d-effect">掩模 3D 效应</a>一课。不要把交替型 trim 流程再讲一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的机制图里，二进制是振幅型、衰减型是弱相移背景。产线语言还要补规格：二元掩模的暗区透过率近似 0、亮区为石英；att-PSM 的「暗」区仍漏过百分之几的光并带约 \\(180^\\circ\\)，亮区仍是石英开口。接触孔与许多 193 nm 层默认衰减型，因为它一次曝光、可走标准 OPC，增益虽小于交替型，但没有相位冲突。更老或更松的层仍用二元铬，写和修都便宜。</p><p><span class="marginnote">直觉类比：衰减相移的「暗区」不是全黑，而是留了一层薄纱——还能透一点点光，但这点光的相位被翻了半圈，与邻边亮区的光反着相，恰好把不想亮的区域压得更暗、边沿切得更陡。二元铬则是彻底拉黑窗帘。</span></p><p>缺口因此是产品选择与薄掩模成像接口，不是再推导相消干涉。没有这层，后面掩模 3D 课的「三维效应」没有对照物——对照物就是：透过率只是 \\((x,y)\\) 上的复数薄屏。</p><h3 id="kirchhoff-薄屏" tabindex="-1">Kirchhoff 薄屏 <a class="header-anchor" href="#kirchhoff-薄屏" aria-label="Permalink to &quot;Kirchhoff 薄屏&quot;">​</a></h3><p>Kirchhoff 近似把掩模写成平面复透过率 \\(t(x,y)\\)，衍射用标量角谱，不进膜厚、不进侧壁、不进波导。OPC 的第一代模型就是它。只要吸收体厚度远小于横向特征、入射接近正入射，误差可接受。193 nm 的 MoSi 厚度已经到波长量级，这个「远小于」开始坏——那是后面掩模 3D 课的账。本课先允许薄屏，否则 3D 修正没有零阶。</p><p><span class="marginnote">数字实例：「6% 衰减」指的是强度；光强正比于振幅平方，所以暗/亮的振幅比约为 \\(\\sqrt{0.06}\\approx 0.25\\)。这个四分之一量级的背景振幅正好参与相消干涉、把边缘斜率抬起来——这就是「只漏百分之几」却有用的原因。</span></p><p><span class="marginnote">「6% 衰减」仍是常见讨论值，不是物理常数。透过率、相位由膜系与波长锁定；ArF 版不能当 KrF 的同一 att-PSM 用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选二元：图形松、\\(k_1\\) 高、要修缺陷简单、成本优先。选 att-PSM：需要压零级、抬边缘斜率，尤其是孔与半密图形，且不愿上交替型的 trim。照明仍与 <a href="/litho/off-axis-illumination">OAI</a> 搭配；掩模类型不替代光瞳选择。</p><p>掩模误差因子（MEF）在低 \\(k_1\\) 时大于 1。二元与衰减的 MEF 不同，因为背景光改变了空中像对开口宽度的导数。写 OPC 必须用对应的 \\(t(x,y)\\)，把衰减膜当成「深铬」会系统偏置。</p><h3 id="缺陷与修复" tabindex="-1">缺陷与修复 <a class="header-anchor" href="#缺陷与修复" aria-label="Permalink to &quot;缺陷与修复&quot;">​</a></h3><p>铬缺陷可补镀或挖；衰减膜的相位/透过率缺陷更接近上一课的相位缺陷行为，但比石英台阶交替型容易纳入标准检测。本课不把掩模厂良率写成节点良率。</p>',16)),(t(),B(n,null,{default:E(()=>[l(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIN%5B%22%E4%BA%8C%E5%85%83%E9%93%AC%3A%200%2F1%20%E6%8C%AF%E5%B9%85%22%5D%20--%3E%20THIN%5B%22Kirchhoff%20%E8%96%84%E5%B1%8F%20t(x%2Cy)%22%5D%0A%20%20ATT%5B%22%E8%A1%B0%E5%87%8F%20MoSi%3A%20%E5%BC%B1%E9%80%8F%E8%BF%87%20%2B%20180%C2%B0%22%5D%20--%3E%20THIN%0A%20%20THIN%20--%3E%20AI%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20%2F%20OPC%20%E9%9B%B6%E9%98%B6%22%5D%0A%20%20THIN%20--%3E%20M3D%5B%22%E5%90%8E%E8%AF%BE%3A%20%E6%9C%89%E5%8E%9A%E5%BA%A6%E7%9A%84%E7%94%B5%E7%A3%81%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[e("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"二元：物体频谱由开口决定，零级强，密图形调制靠开口占空比和照明。衰减：背景复振幅与开口干涉，等效削弱零级、在边沿加相消，孤立图形与孔的 NILS 往往更好。两者都还在透射几何里；EUV 反射掩模不是本课的产品。",-1)),(t(),B(n,null,{default:E(()=>[l(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%9A%97%E5%8C%BA%E7%9A%84%E4%B8%A4%E7%A7%8D%E5%81%9A%E6%B3%95%22%5D%20--%3E%20B%5B%22%E4%BA%8C%E5%85%83%E9%93%AC%EF%BC%9A%E6%8C%AF%E5%B9%85%E6%8C%A1%E6%AD%BB%EF%BC%8C%E9%80%8F%E8%BF%87%E7%8E%87%E8%BF%91%E4%BC%BC%200%22%5D%0A%20%20M%20--%3E%20A%5B%22att-PSM%EF%BC%9A%E6%BC%8F%E7%99%BE%E5%88%86%E4%B9%8B%E5%87%A0%E7%9A%84%E5%85%89%EF%BC%8C%E5%B8%A6%20180%C2%B0%20%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E9%9B%B6%E7%BA%A7%E5%BC%BA%EF%BC%8C%E8%BE%B9%E6%B2%BF%E6%96%9C%E7%8E%87%E4%B8%80%E8%88%AC%EF%BC%8C%E5%A5%BD%E4%BF%AE%E5%A5%BD%E6%A3%80%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E8%83%8C%E6%99%AF%E4%B8%8E%E5%BC%80%E5%8F%A3%E7%9B%B8%E6%B6%88%EF%BC%8C%E5%8E%8B%E9%9B%B6%E7%BA%A7%E6%8A%AC%E6%96%9C%E7%8E%87%22%5D%0A%20%20A2%20--%3E%20G%5B%22%E5%AD%94%E4%B8%8E%E5%8D%8A%E5%AF%86%E5%9B%BE%E5%BD%A2%E7%9A%84%20NILS%20%E6%9B%B4%E5%A5%BD%22%5D%0A%20%20B2%20--%3E%20O%5B%22%E6%9D%BE%E5%B1%82%E4%B8%8E%20LELE%20%E5%88%86%E8%A7%A3%E5%90%8E%E7%9A%84%E7%96%8F%E7%89%88%E4%BB%8D%E5%B8%B8%E7%94%A8%22%5D%0A%20%20A2%20--%3E%20O%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>薄屏假设忽略开口里的波导相移，于是左右边缘对称、HV 无偏置。真实膜一厚，这些对称性破裂——后面的掩模 3D 课专门收这笔。本课的后课接口是：凡说「二元 / att-PSM 成像」，先给出 \\(t(x,y)\\)，再声明是否加 3D。</p><p>检测：二元铬缺陷可补镀或挖铬；衰减膜的相位/透过率缺陷更难修。这是成本差的一部分。LELE 的每一张分解掩模仍要从二元或 att 里选：分解后节距变疏，有时二元就够，不必每张都上 att。</p><p><span class="marginnote">常见误区：以为 LELE 分解后每张版都得跟着升级成 att-PSM。分解后的节距变疏、\\(k_1\\) 变松，有时二元铬反而更便宜更好检。掩模类型按每张版单独选，不是整套自动升级。</span></p><p><span class="marginnote">「6% 衰减」是常见工艺讨论值，不是物理学常数。具体透过率由掩模膜系与层类型决定。换透过率等于换零级与一级的振幅比，TCC 与 OPC 要重校。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交替型 PSM、无铬相移仍是上一课的家族成员，不是本课的下单默认。本课也不讲多电子束如何把版写出来。浸没流体与掩模无关。禁止把 att-PSM 写成「已经包含掩模 3D」：衰减是薄膜光学设计，3D 是厚度与入射角的电磁修正。</p><p>SRAF（亚分辨率辅助图形）画在同一张二元或衰减版上，仍用薄屏 \\(t(x,y)\\) 当零阶；辅助条本身更窄，会更早感到 3D。本课不展开 SRAF 规则，只承认它们属于物体透过率，不是另一种膜系。</p><p><span class="marginnote">铬二元在深紫外仍有反射，需要抗反射层以免鬼像。那是掩模膜系工程，与 att-PSM 的 180° 背景不是同一项规格。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DUV 量产透射版主要是二元铬与衰减相移两类。</li><li>衰减型一次曝光、压零级；二元型简单、松层仍用。</li><li>零阶成像是 Kirchhoff 薄屏 \\(t(x,y)\\)。</li><li>MEF 与 OPC 必须用对膜系，不能把 MoSi 当深铬。</li><li>交替相移的 trim 下一课；吸收体厚度的电磁效应在后面的 3D 课。</li><li>出处：Mack / Levinson；相移量产膜系惯例（Levenson 之后）。</li></ul>',10))])}const S=s(h,[["render",d]]);export{P as __pageData,S as default};
